($q$כמה חומר צריך למטבח?$q$, $q$מודדים גובה ורוחב של כל חזית, מחברים ומוסיפים כ-10% רזרבה. רוחב הגליל הוא 122 ס"מ.$q$, '{kitchen}', null, 23),
