($q$אפשר להניח סיר חם על המשטח?$q$, $q$מומלץ להשתמש בתחתית לסירים ובקרש חיתוך, כמו בכל משטח עבודה, כדי לשמור על הציפוי לאורך זמן.$q$, '{countertop}', null, 31),
