($q$כמה חומר צריך לארון חשמל?$q$, $q$מודדים גובה ורוחב של דלת הארון ומוסיפים כמה סנטימטרים לכל צד לקיפול.$q$, '{electric-cabinet}', null, 35),
($q$הארון נשאר נגיש אחרי ההדבקה?$q$, $q$כן. מדביקים על הדלת של הארון בלבד, והיא נפתחת ונסגרת כרגיל.$q$, '{electric-cabinet}', null, 36),
